<script setup lang="ts">
import {ref,reactive,onMounted,watch} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,get,message} from '../api';import {useAuth} from '../stores/auth';import {date,label} from '../fulfillment';
const props=defineProps<{includeTest:boolean}>(),auth=useAuth(),router=useRouter(),risks=ref<any[]>([]),total=ref(0),signals=ref<any[]>([]),nodes=ref<any[]>([]),busy=ref(false),error=ref(''),saving=ref(false),page=ref(1),signalOpen=ref(false),signalError=ref(''),weatherOpen=ref(false),editId=ref('');
const form=reactive<any>({}),weather=reactive({city:'',nodeId:''}),state:Record<string,string>={NEW:'新发生',ONGOING:'持续中',RECOVERED:'已恢复'};
async function load(){busy.value=true;try{const [history,input]=await Promise.all([get('/alerts/history',{includeTest:String(props.includeTest),page:page.value,pageSize:20}),get('/monitoring/signals',{includeTest:String(props.includeTest)})]);risks.value=history.items;total.value=history.total;signals.value=input;error.value='';}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function refresh(){busy.value=true;try{const tasks=await get('/tracking/tasks',{includeTest:String(props.includeTest),pageSize:20});for(const t of tasks.items)await api.post('/eta/tasks/'+t.id+'/refresh',null,{params:{includeTest:String(props.includeTest)},timeout:45000});await load();ElMessage.success('当前任务的预测与风险已重新评估');}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function begin(s?:any){editId.value=s?.id||'';signalError.value='';try{nodes.value=(await get('/transport-nodes',{pageSize:100})).items||await get('/transport-nodes');}catch{nodes.value=[];}Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,s?{kind:s.kind,name:s.name,nodeId:s.nodeId||'',region:s.region,bounds:typeof s.bounds==='string'?JSON.parse(s.bounds):s.bounds,level:s.level,delayMinutes:s.delayMinutes,details:s.details,source:s.source,sourceUrl:s.sourceUrl,observedAt:s.observedAt,validFrom:s.validFrom,validTo:s.validTo,isTestData:s.isTestData,version:s.version}:{kind:'PORT',name:'',nodeId:'',region:'',bounds:[],level:'MEDIUM',delayMinutes:0,details:'',source:'',sourceUrl:'',observedAt:new Date().toISOString(),validFrom:new Date().toISOString(),validTo:new Date(Date.now()+86400000).toISOString(),isTestData:import.meta.env.DEV});signalOpen.value=true;}
async function save(){saving.value=true;signalError.value='';try{const data={...form,nodeId:form.nodeId||undefined};if(editId.value)await api.put('/monitoring/signals/'+editId.value,data);else await api.post('/monitoring/signals',data);signalOpen.value=false;await refresh();}catch(e){signalError.value=message(e);}finally{saving.value=false;}}
async function showWeather(){try{const result=await get('/transport-nodes');nodes.value=Array.isArray(result)?result:result.items;weatherOpen.value=true;signalError.value='';}catch(e){error.value=message(e);}}
async function syncWeather(){saving.value=true;signalError.value='';try{await api.post('/monitoring/weather',weather,{timeout:65000});weatherOpen.value=false;await refresh();}catch(e){signalError.value=message(e);}finally{saving.value=false;}}
const active=(s:any)=>new Date(s.validFrom)<=new Date()&&new Date(s.validTo)>new Date();watch(()=>props.includeTest,()=>{page.value=1;load();});onMounted(load);
</script>
<template><section class="prediction-center"><header><div><h2>预测与预警记录</h2><p>保留首次发生、持续与恢复记录；外部态势按来源有效期匹配节点和运输路线。</p></div><div><el-button :loading="busy" @click="refresh">重新评估当前任务</el-button><el-button v-if="auth.can('data:write')" @click="begin()">登记港口 / 环境态势</el-button><el-button v-if="auth.can('data:write')" @click="showWeather">同步节点气象</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="risks" v-loading="busy"><el-table-column prop="taskNo" label="运输任务" min-width="200"/><el-table-column label="风险与依据" min-width="310"><template #default="{row}"><el-tag :type="row.level==='HIGH'?'danger':'warning'" size="small">{{row.level==='HIGH'?'高风险':'需关注'}}</el-tag> {{row.message}}</template></el-table-column><el-table-column label="生命周期" width="110"><template #default="{row}"><el-tag :type="row.status==='RECOVERED'?'success':'info'">{{state[row.status]}}</el-tag></template></el-table-column><el-table-column label="发生 / 最新评估" min-width="190"><template #default="{row}">{{date(row.firstSeenAt)}}<small>{{date(row.lastSeenAt)}}{{row.recoveredAt?' · 已恢复':''}}</small></template></el-table-column><el-table-column width="110"><template #default="{row}"><el-button link type="primary" @click="router.push('/tracking/journeys?taskId='+row.taskId)">查看任务 →</el-button></template></el-table-column><template #empty><el-empty description="尚无预警记录，可重新评估当前任务" :image-size="55"/></template></el-table><div class="prediction-pagination"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></div><h3>港口与环境数据来源</h3><el-empty v-if="!signals.length" description="尚无有效来源登记；港口、气象及政策风险需要数据依据" :image-size="55"/><div class="signal-grid"><article v-for="s in signals" :key="s.id"><header><strong>{{s.name}}</strong><el-tag :type="active(s)?s.level==='HIGH'?'danger':s.level==='LOW'?'success':'warning':'info'">{{active(s)?s.level==='LOW'?'一般态势':'风险提示':'已过期 / 待生效'}}</el-tag></header><p>{{s.details}}</p><small>{{s.kind==='PORT'?'港口拥堵':'环境风险'}} · {{s.source}} · 来源登记</small><small>采集 {{date(s.observedAt)}} · 有效至 {{date(s.validTo)}}</small><small v-if="s.delayMinutes">参考等待 {{s.delayMinutes}} 分钟</small><a v-if="s.sourceUrl" :href="s.sourceUrl" target="_blank" rel="noopener noreferrer">查看原始来源 →</a><el-button v-if="auth.can('data:write')" link @click="begin(s)">更新态势</el-button></article></div></section>
<el-dialog v-model="signalOpen" title="登记港口 / 环境态势" width="760px"><el-alert v-if="signalError" :title="signalError" type="error" :closable="false"/><el-form label-position="top"><div class="signal-form"><el-form-item label="类型"><el-select v-model="form.kind"><el-option value="PORT" label="港口态势"/><el-option value="ENVIRONMENT" label="环境异常"/></el-select></el-form-item><el-form-item label="事件 / 态势名称"><el-input v-model="form.name" aria-label="态势名称"/></el-form-item><el-form-item label="关联节点"><el-select v-model="form.nodeId" aria-label="态势关联节点" clearable filterable><el-option v-for="n in nodes.filter(n=>form.kind==='PORT'?n.type==='PORT':true)" :key="n.id" :value="n.id" :label="n.name"/></el-select></el-form-item><el-form-item label="区域"><el-input v-model="form.region"/></el-form-item><el-form-item label="等级"><el-select v-model="form.level"><el-option value="LOW" label="一般态势"/><el-option value="MEDIUM" label="需关注"/><el-option value="HIGH" label="高风险"/></el-select></el-form-item><el-form-item label="参考等待 / 延误（分钟）"><el-input-number v-model="form.delayMinutes" :min="0" :max="10080"/></el-form-item><el-form-item label="数据来源"><el-input v-model="form.source" aria-label="态势来源"/></el-form-item><el-form-item label="来源链接（HTTPS）"><el-input v-model="form.sourceUrl" aria-label="态势来源链接"/></el-form-item><el-form-item label="采集时间"><el-date-picker v-model="form.observedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item label="生效时间"><el-date-picker v-model="form.validFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item label="失效时间"><el-date-picker v-model="form.validTo" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item v-if="form.kind==='ENVIRONMENT'&&!form.nodeId" label="影响范围（GCJ02）"><div class="bounds-inputs"><el-input-number v-for="(l,i) in ['最小经度','最小纬度','最大经度','最大纬度']" :key="l" v-model="form.bounds[i]" :aria-label="l" :precision="4" :controls="false"/></div></el-form-item></div><el-form-item label="影响说明 / 数据依据"><el-input v-model="form.details" aria-label="态势影响说明" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="signalOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并评估</el-button></template></el-dialog>
<el-dialog v-model="weatherOpen" title="同步节点实时气象" width="560px"><el-alert v-if="signalError" :title="signalError" type="error" :closable="false"/><p class="weather-note">从高德天气服务获取实况，保留数据时间；仅作为环境提示，通行与禁航仍以官方通知为准。</p><el-form label-position="top"><el-form-item label="节点"><el-select v-model="weather.nodeId" aria-label="气象节点"><el-option v-for="n in nodes" :key="n.id" :value="n.id" :label="n.name"/></el-select></el-form-item><el-form-item label="节点所在地六位行政编码"><el-input v-model="weather.city" aria-label="气象行政编码" maxlength="6"/></el-form-item></el-form><template #footer><el-button @click="weatherOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="syncWeather">获取气象并评估</el-button></template></el-dialog>
</template>
<style scoped>.prediction-center{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:20px;margin:20px 0}.prediction-center>header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:20px}.prediction-center h2{font-size:16px}.prediction-center h3{font-size:14px;margin:20px 0 16px}.prediction-center header p,.weather-note{font-size:11px;color:var(--text-secondary);line-height:1.8;margin:8px 0}.prediction-center>header>div:last-child{display:flex;gap:12px;flex-wrap:wrap}.prediction-center :deep(.el-table small){display:block;font-size:11px;color:var(--text-secondary);margin-top:6px}.prediction-pagination{display:flex;justify-content:flex-end;padding:20px 0}.signal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.signal-grid article{padding:16px;border:1px solid var(--border);border-radius:6px;line-height:1.8;font-size:12px}.signal-grid header{display:flex;justify-content:space-between;gap:12px;align-items:center}.signal-grid p{margin:12px 0}.signal-grid small{display:block;font-size:10px;color:var(--text-secondary)}.signal-grid a{display:inline-block;color:var(--info);font-size:11px;margin:12px 12px 0 0}.signal-form{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.signal-form :deep(.el-date-editor){width:100%}.bounds-inputs{display:grid;grid-template-columns:1fr 1fr;gap:8px}.bounds-inputs .el-input-number{width:100%}@media(max-width:850px){.prediction-center>header{flex-direction:column}.signal-grid{grid-template-columns:1fr}}@media(max-width:600px){.signal-form{grid-template-columns:1fr}.prediction-center{padding:16px}}</style>
